const MAX_BINARY_BYTES = 8 * 1024 * 1024;

export class AnalysisInputTooLargeError extends Error {
  constructor(label, maxBytes) {
    super(`${label} exceeds ${maxBytes} bytes`);
    this.name = "AnalysisInputTooLargeError";
    this.code = "analysis_input_too_large";
  }
}

export function bounded(buffer, label = "input") {
  if (!Buffer.isBuffer(buffer)) buffer = Buffer.from(buffer);
  if (buffer.length > MAX_BINARY_BYTES) {
    throw new AnalysisInputTooLargeError(label, MAX_BINARY_BYTES);
  }
  return buffer;
}
