export class BoundedDeque {
  /**
   * @param {number} capacity - maximum number of items the deque can hold
   */
  constructor(capacity) {
    this.capacity = capacity;
    this.buffer = new Array(capacity);
    this.head = 0;
    this.count = 0;
  }

  /**
   * Appends an item to the tail. If the deque is full,
   * the oldest item (at head) is overwritten.
   * @param {*} item
   */
  push(item) {
    const tail = (this.head + this.count) % this.capacity;
    this.buffer[tail] = item;
    if (this.count < this.capacity) {
      this.count++;
    } else {
      this.head = (this.head + 1) % this.capacity;
    }
  }

  /**
   * Current number of items in the deque.
   * @type {number}
   */
  get size() {
    return this.count;
  }

  /**
   * Returns a new array containing items from oldest to newest.
   * @returns {Array<*>}
   */
  toArray() {
    if (this.count === 0) return [];
    const result = new Array(this.count);
    let i = 0;
    for (let j = this.head; j < this.capacity; j++) {
      result[i] = this.buffer[j];
      i++;
    }
    for (let j = 0; j < this.head; j++) {
      result[i] = this.buffer[j];
      i++;
    }
    return result;
  }

  /**
   * Clears the deque, resetting head and count.
   */
  clear() {
    this.head = 0;
    this.count = 0;
  }
}
