export function optimize(items, maxBytes) {
  let bytesAccum = 0;
  let overflow = false;
  const events = [];

  for (const item of items) {
    let bytes = 0;

    // Fast path: pure-ASCII structure (no non-ASCII chars anywhere)
    if (isPureAscii(item)) {
      bytes = computeAsciiBytes(item);
    } else {
      // Fallback: non-ASCII somewhere, use JSON.stringify + Buffer.byteLength
      bytes = Buffer.byteLength(JSON.stringify(item));
    }

    if (bytesAccum + bytes > maxBytes) {
      overflow = true;
      break;
    }

    events.push(item);
    bytesAccum += bytes;
  }

  return { events, bytes: bytesAccum, overflow };
}

function isPureAscii(item) {
  if (typeof item === 'string') {
    return item.length === 0 || item.charCodeAt(item.length - 1) < 128;
  }
  if (Array.isArray(item)) {
    for (let i = 0; i < item.length; i++) {
      if (!isPureAscii(item[i])) return false;
    }
    return true;
  }
  if (typeof item === 'object' && item !== null) {
    for (const key of Object.keys(item)) {
      if (!isPureAscii(key)) return false;
    }
    for (const value of Object.values(item)) {
      if (!isPureAscii(value)) return false;
    }
    return true;
  }
  // number, boolean, null are always ASCII
  return true;
}

function computeAsciiBytes(item) {
  if (typeof item === 'string') {
    return computeStringBytes(item);
  }
  if (Array.isArray(item)) {
    let bytes = 0;
    bytes += 1; // '['
    for (let i = 0; i < item.length; i++) {
      if (i > 0) bytes += 1; // ','
      bytes += computeAsciiBytes(item[i]);
    }
    bytes += 1; // ']'
    return bytes;
  }
  if (typeof item === 'object' && item !== null) {
    let bytes = 1; // '{'
    const keys = Object.keys(item);
    for (let i = 0; i < keys.length; i++) {
      if (i > 0) bytes += 2; // ', '
      bytes += computeStringBytes(keys[i]);
      bytes += 2; // ': '
      bytes += computeAsciiBytes(item[keys[i]]);
    }
    bytes += 1; // '}'
    return bytes;
  }
  // number or boolean
  return String(item).length;
}

function computeStringBytes(s) {
  let bytes = 2; // surrounding quotes
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code === 0x22) { // "
      bytes += 4; // \"
    } else if (code === 0x5C) { // \
      bytes += 4; // \\
    } else if (code >= 0x09 && code <= 0x0D) { // \t, \n, \r
      bytes += 4; // \t, \n, \r
    } else if (code === 0x08) { // \b
      bytes += 4; // \b
    } else if (code === 0x0C) { // \f
      bytes += 4; // \f
    } else if (code >= 0x00 && code <= 0x1F) {
      bytes += 6; // \uXXXX
    } else {
      bytes += 1;
    }
  }
  return bytes;
}
