export class BoundedDeque {
    /**
     * @param {number} capacity The maximum number of elements the deque can hold.
     */
    constructor(capacity) {
        if (capacity <= 0) {
            throw new Error("Capacity must be a positive number.");
        }
        this.capacity = capacity;
        this.buffer = new Array(capacity);
        this.head = 0; // Index where the next item will be pushed (or where the oldest item is)
        this.count = 0; // Current number of elements in the deque
    }

    /**
     * Appends an item to the deque. If the deque is full, it overwrites the oldest item.
     * O(1) complexity.
     * @param {*} item The item to add.
     */
    push(item) {
        this.buffer[this.head] = item;

        if (this.count < this.capacity) {
            // If not full, increment count
            this.count++;
        } else {
            // If full, we are overwriting the oldest item (which is at the current head position)
            // The head advances to the next position, effectively dropping the oldest item.
            this.head = (this.head + 1) % this.capacity;
        }
    }

    /**
     * Returns the current number of elements in the deque.
     * @returns {number} The size of the deque.
     */
    get size() {
        return this.count;
    }

    /**
     * Returns an array of the elements from oldest to newest.
     * The order is determined by the ring buffer structure.
     * O(N) complexity, where N is the capacity.
     * @returns {Array<*>} An array containing all elements from oldest to newest.
     */
    toArray() {
        const result = [];
        if (this.count === 0) {
            return result;
        }

        // Determine the starting point (the oldest item).
        // If head is 0, the oldest item is at index 0.
        // If head is N, the oldest item is at index N.
        // Since we overwrite, the oldest item is always at the index *after* the current head position,
        // wrapping around.

        // The oldest item is the one that was pushed earliest.
        // If count < capacity, the oldest item is at index 0.
        // If count == capacity, the oldest item is at index 'head'.

        let startIndex;
        if (this.count < this.capacity) {
            // If not full, items are 0, 1, ..., count-1
            startIndex = 0;
        } else {
            // If full, the oldest item is at the current head position.
            startIndex = this.head;
        }

        for (let i = 0; i < this.count; i++) {
            const index = (startIndex + i) % this.capacity;
            result.push(this.buffer[index]);
        }

        return result;
    }

    /**
     * Clears all elements from the deque.
     * O(1) complexity.
     */
    clear() {
        this.head = 0;
        this.count = 0;
        // Note: We don't need to clear the buffer array itself, as subsequent pushes
        // will overwrite the slots, and count will be 0.
    }
